{
  "name": "数据采集模块",
  "name_en": "Data Acquisition Module",
  "manufacturer": "Zurich Instruments",
  "description": "这是一个非物理的软件模块，用于 Zurich Instruments 的 LabOne 环境中，从多个仪器信号源按设定数据率采集、对齐并读取时域或频域数据。它支持连续采集、基于触发条件的突发采集，以及手动触发与采集结果读取，常用于实验测量过程中的数据记录与分析。",
  "description_en": "This is a non-physical software module used in the Zurich Instruments LabOne environment to acquire, align, and read time-domain or frequency-domain data from multiple instrument signal sources at a defined data rate. It supports continuous acquisition, trigger-based burst acquisition, manual triggering, and readout of acquired data for laboratory measurement and analysis workflows.",
  "actions": [
    {
      "action_name": "auto-finish",
      "description": "停止数据采集模块。",
      "description_en": "Stop the data acquisition module."
    },
    {
      "action_name": "auto-finished",
      "description": "获取采集是否已完成。",
      "description_en": "Get whether the acquisition has finished."
    },
    {
      "action_name": "auto-read",
      "description": "读取模块已采集的数据，数据可按突发分段返回。",
      "description_en": "Read the data acquired by the module; the data may be returned split into bursts."
    },
    {
      "action_name": "auto-trigger",
      "description": "执行一次手动触发。",
      "description_en": "Execute a manual trigger."
    }
  ],
  "tag_hints": [
    "LabOne software module",
    "data acquisition",
    "triggered recording",
    "time-domain capture",
    "frequency-domain capture",
    "burst readout",
    "Zurich Instruments"
  ]
}

